-- =====================================================================
-- Catálogos (RF-54) y asistente de bienvenida
--  - Catálogos base de LOGIKS (empresa_id nulo): puertos, aeropuertos,
--    ciudades, contenedores y conceptos logísticos comunes. Cada empresa
--    agrega los suyos.
--  - Configuración por empresa: hitos por tipo, términos por defecto,
--    servicios que presta y si ya completó la bienvenida.
-- =====================================================================
alter table public.empresas add column if not exists hitos_por_tipo jsonb not null default '{}';
alter table public.empresas add column if not exists terminos text;
alter table public.empresas add column if not exists servicios text[] not null default '{}';
alter table public.empresas add column if not exists configurada boolean not null default false;
update public.empresas set configurada = true;

create unique index if not exists catalogos_unicos on public.catalogos (coalesce(empresa_id, '00000000-0000-0000-0000-000000000000'::uuid), tipo, lower(nombre));

on conflict do nothing;
